  --omb-surface-subtle: #E7E1E9;
  --omb-surface-hover: #E4DDE5;
  --omb-surface-composer: #FCFBFD;
  --omb-composer-ring: rgba(122, 82, 64, 0.18);
  --omb-surface-code: #EDE7EE;
  --omb-surface-code-block: #F4F0F5;
  --omb-surface-table: #FAF8FA;
  --omb-surface-table-head: #F1ECF2;
  --omb-surface-table-zebra: rgba(31, 27, 36, 0.02);
